def build_index_from_tokenizer(array, tokenizer, truncate=False, batch_size=100000, avoid_copies=True):
    """Builds an index from the given array and tokenizer, handling large arrays by processing them in batches if necessary."""
    # Initialize the index
    index = {"term_matrix": [], "positions": [], "term_dict": {}, "avg_doc_len": 0, "doc_lengths": []}

    # Iterate over the array in batches
    for batch in itertools.zip_longest(*[iter(array)] * batch_size):
        # Tokenize the batch
        tokens = [tokenizer(doc) for doc in batch if doc is not None]

        # Update the index
        for i, token in enumerate(tokens):
            if token not in index["term_dict"]:
                index["term_dict"][token] = []
            index["term_dict"][token].append(i)
            index["positions"].append(i)
            index["term_matrix"].append(token)
            index["doc_lengths"].append(len(tokens))

    # Calculate the average document length
    index["avg_doc_len"] = sum(index["doc_lengths"]) / len(index["doc_lengths"])

    return index

class SearchArray:
    @classmethod
    def index(cls, array: Iterable, tokenizer=ws_tokenizer,
              truncate=False, batch_size=100000, avoid_copies=True) -> 'SearchArray':
        """Indexes an array of strings using a specified tokenizer and returns an instance of SearchArray containing the indexed data."""

        # Check if array is list-like and raise a TypeError if not
        if not is_list_like(array):
            raise TypeError("Expected list-like object, got {}".format(type(array)))

        # Build the index from the array and tokenizer
        index = build_index_from_tokenizer(array, tokenizer, truncate, batch_size, avoid_copies)

        # Create a new instance of SearchArray
        return cls(index)

